// SBC value index — record JAH-GPC-SBC-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"cpu_ghz": 2.4, "ram_gb": 8, "price_usd": 80};
var value = (m.cpu_ghz*m.ram_gb/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-SBC-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-SBC-000001|' + value.toFixed(2) + ' SBC index');

